'use strict';
const fields=['sessions','views','carts','checkouts','purchases','purchasing_sessions'];
const qualityFields=['raw_events','observed_days','excluded_identity_events','purchase_events','missing_transaction_events','missing_revenue_events','negative_revenue_events','duplicate_transaction_events'];
const $=id=>document.getElementById(id);let snapshot=null;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=n=>n.toLocaleString('en-US');const pct=(k,n)=>n?(100*k/n).toFixed(2)+'%':'—';
function wilson(k,n){if(!n)return null;const z=1.959963984540054,p=k/n,d=1+z*z/n,c=(p+z*z/(2*n))/d,h=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [Math.max(0,c-h),Math.min(1,c+h)];}
function validDate(s){return typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s)&&!Number.isNaN(Date.parse(s))&&new Date(s).toISOString().slice(0,10)===s;}
function validate(s){if(s.schema_version!==1||s.classification!=='historical_obfuscated_sample')throw Error('Use a version 1 historical GA4 sample snapshot from pipeline.py.');if(!validDate(s.start_date)||!validDate(s.end_date)||s.start_date<'2020-11-01'||s.end_date>'2021-01-31'||s.start_date>s.end_date)throw Error('Invalid extraction dates.');if(!Array.isArray(s.rows)||!s.rows.length)throw Error('Snapshot contains no aggregate rows.');const keys=new Set();for(const r of s.rows){if(!validDate(r.date)||r.date<s.start_date||r.date>s.end_date)throw Error('Row outside extraction dates.');if(!['device','acquisition_source'].every(f=>typeof r[f]==='string'&&r[f].length))throw Error('Missing dimension.');let key=JSON.stringify([r.date,r.device,r.acquisition_source]);if(keys.has(key))throw Error('Duplicate aggregate grain.');keys.add(key);if(!fields.every(f=>Number.isSafeInteger(r[f])&&r[f]>=0))throw Error('Counts must be nonnegative safe integers.');if(!(r.sessions>=r.views&&r.views>=r.carts&&r.carts>=r.checkouts&&r.checkouts>=r.purchases&&r.purchases<=r.purchasing_sessions&&r.purchasing_sessions<=r.sessions))throw Error('Funnel counts are not nested.');}let q=s.quality;if(!q||!qualityFields.every(f=>Number.isSafeInteger(q[f])&&q[f]>=0))throw Error('Missing or invalid quality checks.');if(!q.raw_events||q.excluded_identity_events>q.raw_events||q.observed_days>(Date.parse(s.end_date)-Date.parse(s.start_date))/86400000+1)throw Error('Invalid event coverage.');let t=total(s.rows);if(t.sessions>q.raw_events-q.excluded_identity_events||t.purchasing_sessions>q.purchase_events||qualityFields.slice(4).some(f=>q[f]>q.purchase_events))throw Error('Quality counts do not reconcile.');return s;}
function total(rows){return Object.fromEntries(fields.map(f=>[f,rows.reduce((a,r)=>a+r[f],0)]));}
function groups(rows,dim){const m=new Map();for(const r of rows){if(!m.has(r[dim]))m.set(r[dim],[]);m.get(r[dim]).push(r);}return [...m].map(([key,rs])=>({key,...total(rs)}));}
function table(rows){return '<table><thead><tr><th>Segment</th><th>Sessions</th><th>Views</th><th>Ordered purchases</th><th>Completion</th><th>95% interval</th></tr></thead><tbody>'+rows.map(r=>{let ci=wilson(r.purchases,r.views);return '<tr><td>'+esc(r.key)+'</td><td>'+num(r.sessions)+'</td><td>'+num(r.views)+'</td><td>'+num(r.purchases)+'</td><td>'+pct(r.purchases,r.views)+'</td><td>'+(ci?ci.map(v=>(v*100).toFixed(2)+'%').join(' – '):'—')+'</td></tr>';}).join('')+'</tbody></table>';}
function showTab(id){document.querySelectorAll('.panel').forEach(p=>p.hidden=p.id!==id);document.querySelectorAll('.tab').forEach(b=>{b.classList.toggle('active',b.dataset.tab===id);b.setAttribute('aria-current',b.dataset.tab===id?'page':'false');});}
function warnings(s){let out=qualityFields.filter(f=>!['raw_events','observed_days','purchase_events'].includes(f)&&s.quality[f]>0);const days=(Date.parse(s.end_date)-Date.parse(s.start_date))/86400000+1;if(s.quality.observed_days!==days)out.push('incomplete_day_coverage');return out;}
function selected(){return snapshot.rows.filter(r=>r.date>=$('from').value&&r.date<=$('through').value&&(!$('device').value||r.device===$('device').value)&&(!$('source').value||r.acquisition_source===$('source').value));}
function render(){if(!snapshot)return;const rows=selected(),t=total(rows),labels=['Product view','Add to cart','Begin checkout','Purchase'];$('scope').textContent=`${$('from').value} through ${$('through').value} · ${rows.length} aggregate rows · Device: ${$('device').value||'All'} · First-user source: ${$('source').value||'All'}`;$('export').disabled=!rows.length;$('metrics').innerHTML=[['Sessions',num(t.sessions)],['Product-view sessions',num(t.views)],['Ordered purchases',num(t.purchases)],['View → purchase',pct(t.purchases,t.views)]].map(([l,v])=>`<div class="metric"><span>${l}</span><strong>${v}</strong></div>`).join('');$('funnel').innerHTML=['views','carts','checkouts','purchases'].map((f,i)=>`<div class="barrow"><div class="barlabel"><span>${labels[i]}</span><span>${num(t[f])} · ${pct(t[f],t.views)}</span></div><div class="track"><div class="bar" style="width:${t.views?100*t[f]/t.views:0}%"></div></div></div>`).join('');let drops=['views','carts','checkouts'].map((f,i)=>({i,n:t[f]-t[['carts','checkouts','purchases'][i]],base:t[f]})).sort((a,b)=>b.n-a.n);let d=drops[0];$('insight').innerHTML=(!rows.length?'<p>No rows match these filters.</p>':(warnings(snapshot).length?'<div class="note">Source-wide quality exceptions need review before acting on segment differences.</div>':'')+(t.views?`<h2>${num(d.n)} sessions leave the ordered funnel</h2><p>The largest count drop is ${labels[d.i].toLowerCase()} → ${labels[d.i+1].toLowerCase()} (${pct(d.n,d.base)} of that stage). This includes missing or out-of-order tracking; it is not necessarily abandonment.</p><p><strong>Next investigation:</strong> compare device and source mix, verify event instrumentation, then propose a controlled test of the relevant experience.</p>`:'<p>No product-view sessions in this selection. Completion cannot be estimated.</p>'));$('devices').innerHTML=table(groups(rows,'device').sort((a,b)=>b.views-a.views));$('sources').innerHTML=table(groups(rows,'acquisition_source').sort((a,b)=>b.views-a.views));$('daily').innerHTML=table(groups(rows,'date').sort((a,b)=>a.key.localeCompare(b.key)));}
function load(s){snapshot=validate(s);$('empty').hidden=true;$('results').hidden=false;$('status').textContent='Snapshot loaded';$('coverage').textContent=`${s.start_date} – ${s.end_date} · Historical obfuscated sample`;$('from').value=s.start_date;$('through').value=s.end_date;for(const id of ['from','through']){$(id).min=s.start_date;$(id).max=s.end_date;}for(const [id,dim]of[['device','device'],['source','acquisition_source']]){$(id).innerHTML='<option value="">All</option>'+[...new Set(s.rows.map(r=>r[dim]))].sort().map(v=>`<option value="${esc(v)}">${esc(v)}</option>`).join('');}$('qualityContent').innerHTML=`<p>Extraction window: ${s.start_date} – ${s.end_date}. Generated: ${esc(s.generated_at||'not supplied')}.</p>`+(warnings(s).length?'<div class="note">Quality exceptions detected. Counts below may overlap; do not add them together.</div>':'<p class="positive">No flagged checks. Tracking completeness is not established by these checks alone.</p>')+'<table><thead><tr><th>Check</th><th>Count</th></tr></thead><tbody>'+qualityFields.map(f=>`<tr><td>${f.replaceAll('_',' ')}</td><td>${num(s.quality[f])}</td></tr>`).join('')+'</tbody></table>'+(warnings(s).includes('incomplete_day_coverage')?'<p class="note">Fewer observed dates than requested. Investigate event coverage or missing partitions.</p>':'');render();showTab('overview');}
if(typeof document!=='undefined'){document.querySelectorAll('.tab').forEach(b=>b.onclick=()=>showTab(b.dataset.tab));$('openSetup').onclick=()=>showTab('setup');$('file').onchange=async e=>{const f=e.target.files[0];if(!f)return;$('error').textContent='';try{if(f.size>20*1024*1024)throw Error('Snapshot exceeds the 20 MB import limit. Use a shorter extraction window.');load(JSON.parse(await f.text()));}catch(err){$('error').textContent='Import rejected: '+err.message+' Previous valid snapshot, if any, is unchanged.';}e.target.value='';};for(const id of ['from','through','device','source'])$(id).onchange=render;$('reset').onclick=()=>load(snapshot);$('export').onclick=()=>{let title='Conversion diagnostic brief';let body='<h1>'+title+'</h1><p>'+esc($('scope').textContent)+'</p><p>Historical obfuscated GA4 sample. Source: bigquery-public-data.ga4_obfuscated_sample_ecommerce.events_*</p>'+$('insight').innerHTML+'<h2>Device comparison</h2>'+$('devices').innerHTML+'<h2>Acquisition-source comparison</h2>'+$('sources').innerHTML+'<h2>Daily cohorts</h2>'+$('daily').innerHTML+'<h2>Source-wide quality (unfiltered)</h2>'+$('qualityContent').innerHTML+'<p>Ordered session funnel; strict increasing timestamps. Completion = ordered purchases / product-view sessions. Descriptive Wilson intervals assume independent sessions; repeated visitors may violate this assumption. First-user source is not campaign attribution. No causal or profitability conclusions.</p>';let blob=new Blob(['<!doctype html><meta charset="utf-8"><title>'+title+'</title><style>body{font:15px/1.6 system-ui;max-width:1100px;margin:35px auto;padding:25px}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:10px;border-bottom:1px solid #ddd}</style>'+body],{type:'text/html'});let a=document.createElement('a'),url=URL.createObjectURL(blob);a.href=url;a.download='conversion-brief.html';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};}
if(typeof module!=='undefined')module.exports={validate,wilson,total,groups};
